import{_ as o,o as i,c as n,a2 as t}from"./chunks/framework.Io1M4tdt.js";const p=JSON.parse('{"title":"Configuration","description":"How to configure Bump My Version","frontmatter":{"title":"Configuration","description":"How to configure Bump My Version","icon":null,"date":"2024-08-11T00:00:00.000Z"},"headers":[],"relativePath":"reference/configuration/index.md","filePath":"reference/configuration/index.md","lastUpdated":1793537972000}'),r={name:"reference/configuration/index.md"};function a(c,e,l,s,d,f){return i(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>Bump My Version looks in three places for configuration information (in order of precedence):</p><ol><li>command line</li><li>configuration file</li><li>environment variables</li></ol><h2 id="configuration-files" tabindex="-1">Configuration files <a class="header-anchor" href="#configuration-files" aria-label="Permalink to &quot;Configuration files&quot;">​</a></h2><p>Bump My Version looks in four places for the configuration file to parse (in order of precedence):</p><ol><li><code>--config-file &lt;FILE&gt;</code> <em>(command line argument)</em></li><li><code>BUMPVERSION_CONFIG_FILE=file</code> <em>(environment variable)</em></li><li><code>.bumpversion.cfg</code> <em>(legacy)</em></li><li><code>.bumpversion.toml</code></li><li><code>setup.cfg</code> <em>(legacy)</em></li><li><code>pyproject.toml</code></li></ol><p>Items 3-6 are searched for in the current directory, then, when inside a git or mercurial repository, in each parent directory up to the repository root. The nearest directory containing a configuration file wins. Outside a repository, only the current directory is searched.</p><p>A <code>.toml</code> file counts as a configuration file when it is valid TOML and contains a <code>[tool.bumpversion]</code> table. A table that only holds <code>[[tool.bumpversion.files]]</code> is enough. Invalid TOML is skipped, not reported as an error. <code>.cfg</code> files must contain a <code>bumpversion</code> section.</p><p>If no file with Bump My Version configuration is found, the nearest <code>pyproject.toml</code> with a static <code>project.version</code> (<a href="https://peps.python.org/pep-0621/" target="_blank" rel="noreferrer">PEP 621</a>) is used instead, and that version becomes the current version. A <code>pyproject.toml</code> that lists <code>version</code> in <code>project.dynamic</code> is ignored.</p><p><code>.toml</code> files are recommended. We will likely drop support for <code>ini</code>-style formats in the future. You should add your configuration file to your source code management system.</p><p>By using a configuration file, you no longer need to specify those options on the command line. The configuration file also allows greater flexibility in specifying how files are modified.</p><h2 id="configuration-sections" tabindex="-1">Configuration sections <a class="header-anchor" href="#configuration-sections" aria-label="Permalink to &quot;Configuration sections&quot;">​</a></h2><ul><li><a href="./global.html">Global</a></li><li><a href="./version-component.html">Version Component</a></li><li><a href="./file.html">File</a></li></ul>',13)])])}const m=o(r,[["render",a]]);export{p as __pageData,m as default};
